#include "DomainCommandCatalogue.hpp"
namespace elysium::simulation {bool DomainCommandCatalogue::addSchema(CommandSchema s,std::string&w){if(!s.type||!s.owner||!s.version){w="command requires owner";return false;}return schemas_.emplace(s.type,s).second;}CommandResult DomainCommandCatalogue::validate(const DomainCommand&c,StableId auth,std::uint64_t rev)const{auto i=schemas_.find(c.type);if(i==schemas_.end())return{false,"undeclared command owner",rev};if(c.issuer!=auth)return{false,"unauthorized issuer",rev};if(c.version>i->second.version)return{false,"unsupported command version",rev};if(c.expectedRevision!=rev)return{false,"target revision mismatch",rev};return{true,"",rev+1};}ContentId DomainCommandCatalogue::ownerOf(ContentId t)const{auto i=schemas_.find(t);return i==schemas_.end()?0:i->second.owner;}}
